mapper.select:
SELECT 
  SUM(STOCK.QTYSTU_0) AS QTY 
FROM EXPLOIT.STOCK STOCK
WHERE STOCK.ITMREF_0=#{PnRoot}
  AND STOCK.STOFCY_0=#{Site}
  AND STOCK.STA_0 != 'RE'

SELECT STUFF((SELECT DISTINCT ';' + T0.OptionPN FROM ( SELECT ITMREFBPS_0 AS OptionPN FROM EXPLOIT.ITMBPS ITMBPS WHERE ITMREF_0 != ITMREFBPS_0 AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ITMREF_0,',',''),'.',''),'-',''),'_',''),'\',''),'/',''),' ','') = #{PnRoot}
UNION SELECT ITMREF_0 AS OptionPN FROM EXPLOIT.ITMBPS ITMBPS WHERE ITMREF_0 != ITMREFBPS_0 AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(ITMREFBPS_0,',',''),'.',''),'-',''),'_',''),'\',''),'/',''),' ','') = #{PnRoot}
UNION SELECT T2.ITMREFBPS_0 AS OptionPN FROM EXPLOIT.ITMBPS T1 INNER JOIN EXPLOIT.ITMBPS T2 ON T1.ITMREF_0 = T2.ITMREF_0 WHERE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(T1.ITMREFBPS_0,',',''),'.',''),'-',''),'_',''),'\',''),'/',''),' ','') = #{PnRoot} AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(T2.ITMREFBPS_0,',',''),'.',''),'-',''),'_',''),'\',''),'/',''),' ','') != #{PnRoot} ) T0 FOR XML PATH('')),1,1,'') AS OptionPN
